import itertools
par={'O':set(),'N':set(),'S':{'O','N'},'U':{'S'},'T':{'N'}}
def anc(X):
    r=set(X); st=list(X)
    while st:
        for p in par[st.pop()]:
            if p not in r: r.add(p); st.append(p)
    return r
def dsep(X,Y,Z):  # ancestral moral graph criterion
    A=anc(X|Y|Z); adj={n:set() for n in A}
    for n in A:
        ps=[p for p in par[n] if p in A]
        for p in ps: adj[n].add(p); adj[p].add(n)
        for p,q in itertools.combinations(ps,2): adj[p].add(q); adj[q].add(p)
    seen=set(X); st=list(X)
    while st:
        for m in adj[st.pop()]:
            if m not in Z and m not in seen: seen.add(m); st.append(m)
    return not (seen & Y)
