import itertools, random
random.seed(7)
def cpt(ch,pa=None):
    if pa is None: p=random.random(); return ((ch,),{(1,):p,(0,):1-p})
    t={}
    for v in (0,1): p=random.random(); t[(v,1)]=p; t[(v,0)]=1-p
    return ((pa,ch),t)
fs=[cpt('F'),cpt('C','F'),cpt('D','C'),cpt('T','D')]
def mult(f,g):
    sc=tuple(dict.fromkeys(f[0]+g[0])); t={}
    for v in itertools.product((0,1),repeat=len(sc)):
        a=dict(zip(sc,v)); t[v]=f[1][tuple(a[x] for x in f[0])]*g[1][tuple(a[x] for x in g[0])]
    return (sc,t)
def sumout(f,x):
    sc=tuple(y for y in f[0] if y!=x); t={}
    for v,p in f[1].items():
        a=dict(zip(f[0],v)); k=tuple(a[y] for y in sc); t[k]=t.get(k,0)+p
    return (sc,t)
def ve(order):
    cur=list(fs); scopes=[]
    for x in order:
        inv=[f for f in cur if x in f[0]]; cur=[f for f in cur if x not in f[0]]
        p=inv[0]
        for g in inv[1:]: p=mult(p,g)
        n=sumout(p,x); scopes.append(n[0]); cur.append(n)
    return scopes,cur[0][1][(1,)]
